+const createSafeSrcdoc = (htmlContent: string): string => {
+  // Parse and reconstruct srcdoc content safely
+  const parser = new DOMParser();
+  const doc = parser.parseFromString(htmlContent, "text/html");
+  
+  // Only allow safe tags and attributes
+  const allowedTags = ["html", "head", "body", "div", "span", "p", "a", "img", "iframe"];
+  const allowedAttributes = ["src", "href", "alt", "title", "style", "class"];
+  
+  const sanitizeNode = (node: Node): string => {
+    if (node.nodeType === Node.TEXT_NODE) {
+      return node.textContent || "";
+    }
+    
+    if (node.nodeType === Node.ELEMENT_NODE) {
+      const element = node as Element;
+      if (!allowedTags.includes(element.tagName.toLowerCase())) {
+        return "";
+      }
+      
+      const attrs = Array.from(element.attributes)
+        .filter(attr => allowedAttributes.includes(attr.name.toLowerCase()))
+        .map(attr => `${attr.name}="${attr.value.replace(/"/g, '&quot;')}"`)
+        .join(" ");
+      
+      const children = Array.from(element.childNodes)
+        .map(child => sanitizeNode(child))
+        .join("");
+      
+      return `<${element.tagName.toLowerCase()}${attrs ? " " + attrs : ""}>${children}</${element.tagName.toLowerCase()}>`;
+    }
+    
+    return "";
+  };
+  
+  const body = doc.body;
+  return sanitizeNode(body) || "";
+};
