+/**
+ * Validate that a sync URL is a trusted Firebase endpoint
+ */
+export function isValidSyncURL(urlString: string): boolean {
+  try {
+    const url = new URL(urlString);
+    
+    // Only allow HTTPS protocol for security
+    if (url.protocol !== 'https:') {
+      return false;
+    }
+    
+    // List of allowed Firebase domains for session sync
+    const allowedDomains = [
+      'firebaseapp.com',
+      'firebase.googleapis.com',
+      'accounts.google.com', // For Google auth sessions
+      /\.firebaseapp\.com$/, // Allow subdomains
+      /\.firebase\.googleapis\.com$/ // Allow subdomains
+    ];
+    
+    // Check if the hostname matches any allowed domain pattern
+    return allowedDomains.some(pattern => 
+      typeof pattern === 'string' 
+        ? url.hostname === pattern || url.hostname.endsWith('.' + pattern)
+        : pattern.test(url.hostname)
+    );
+  } catch {
+    return false; // Invalid URL format
+  }
+}

