+/**
+ * HTML entity encoding for XSS prevention
+ * Encodes only dangerous characters, preserves safe HTML formatting
+ * if needed for note rendering
+ */
+export function escapeHtml(text) {
+  if (!text || typeof text !== 'string') return text;
+  
+  // Encode only the minimum set of characters needed to prevent XSS
+  // while preserving note formatting (like <b>, <i> tags for formatting)
+  // For a note-taking app, we might want to allow safe HTML tags
+  // but this minimal version encodes all HTML special chars
+  
+  return text.replace(/[&<>"'`]/g, function (match) {
+    return {
+      '&': '&amp;',
+      '<': '&lt;',
+      '>': '&gt;',
+      '"': '&quot;',
+      "'": '&#x27;',
+      '`': '&#x60;'
+    }[match];
+  });
+}

