+ * Validation utilities for push notification payloads
+ */
+
+/**
+ * Validates push notification payload structure
+ * @param {Object} data - Push notification payload
+ * @throws {Error} If payload is invalid
+ */
+function validatePushPayload(data) {
+  if (!data || typeof data !== 'object') {
+    throw new Error('Push payload must be an object');
+  }
+
+  // Validate data structure
+  if (data.data && typeof data.data !== 'object') {
+    throw new Error('Push payload data must be an object if present');
+  }
+
+  if (data.where && typeof data.where !== 'object') {
+    throw new Error('Push payload where clause must be an object if present');
+  }
+
+  // Validate notification object if present
+  if (data.notification) {
+    if (typeof data.notification !== 'object') {
+      throw new Error('Push notification must be an object');
+    }
+
+    // Validate platform-specific notifications
+    const platforms = ['ios', 'android', 'web'];
+    for (const platform of platforms) {
+      if (data.notification[platform] && typeof data.notification[platform] !== 'object') {
+        throw new Error(`Push notification for ${platform} must be an object`);
+      }
+    }
+  }
+
+  // Validate expiration time if present
+  if (data.expiration_time !== undefined && data.expiration_time !== null) {
+    if (typeof data.expiration_time !== 'number' || data.expiration_time < 0) {
+      throw new Error('Push expiration_time must be a non-negative number');
+    }
+  }
+}
+
+module.exports = {
+  validatePushPayload
+};

